import os
from typing import Any
import uuid
import time
import base64
from io import BytesIO
from PIL import Image
from google import genai
from google.genai import types
from app.config import settings

# إعداد العميل
client = genai.Client(api_key=settings.google_api_key)

IMAGE_DIR = "rawaj-frontend/assets/image"
os.makedirs(IMAGE_DIR, exist_ok=True)

# الموديل المستخدم (تأكد من توفره في منطقتك، أو استخدم imagen-3 كبديل)
IMAGE_MODEL_NAME = "gemini-3-pro-image-preview" 
IMAGE_MODEL_NAME_ALT = "imagen-3"

# قيود السلامة لمنع ظهور نصوص عشوائية أو عناصر غير مرغوبة
SAFETY_SUFFIX = " . exclude women, exclude females, exclude alcohol, exclude wine, modest. NO TEXT, NO TYPOGRAPHY."

def generate_image(prompt: str, reference_image_path: str = None, aspect_ratio: str = "16:9", thought_signature: Any = None, model_name: str = IMAGE_MODEL_NAME) :
    """
    توليد صورة احترافية باستخدام بروتوكول التفكير والبصمة لضمان التطابق التام عند التعديل.
    """
    print(f"🎨 Generating {aspect_ratio} Image via {model_name}...")

    # 1. تجهيز البرومبت النهائي
    final_prompt = f"{prompt} {SAFETY_SUFFIX}"
    
    # 2. تحويل البصمة من Hex (قاعدة البيانات) إلى Bytes إذا وجدت
    if thought_signature and isinstance(thought_signature, str):
        try:
            if thought_signature.startswith('\\x'): thought_signature = thought_signature[2:]
            thought_signature = bytes.fromhex(thought_signature)
            print("   🧠 Injecting Thought Signature (History Mode)...")
        except: pass

    # 3. بناء المحتوى (Contents)
    contents = []

    if thought_signature and reference_image_path and os.path.exists(reference_image_path):
        # وضع التعديل: نرسل الصورة السابقة مع بصمتها في دور 'model'
        with open(reference_image_path, "rb") as f:
            prev_image_bytes = f.read()

        prev_model_part = types.Part(
            inline_data=types.Blob(mime_type="image/png", data=prev_image_bytes),
            thought_signature=thought_signature # حرج جداً: حقن البصمة هنا
        )
        contents.append(types.Content(role="model", parts=[prev_model_part]))
        
        # طلب المستخدم الجديد
        user_parts = [types.Part(text=f"Update the image based on the reference. {final_prompt}")]
        contents.append(types.Content(role="user", parts=user_parts))
    else:
        # وضع التوليد الأول
        user_parts = [types.Part(text=final_prompt)]
        if reference_image_path and os.path.exists(reference_image_path):
            print(f"   🔗 Using reference image: {reference_image_path}")
            ref_img = Image.open(reference_image_path).convert("RGB")
            img_byte_arr = BytesIO()
            ref_img.save(img_byte_arr, format='PNG')
            user_parts.append(types.Part(inline_data=types.Blob(mime_type="image/png", data=img_byte_arr.getvalue())))
        
        contents.append(types.Content(role="user", parts=user_parts))

    try:
        # 4. استدعاء الـ API مع تفعيل TEXT و IMAGE في الـ modalities
        response = client.models.generate_content(
            model=IMAGE_MODEL_NAME,
            contents=contents,
            config=types.GenerateContentConfig(
                image_config=types.ImageConfig(aspect_ratio=aspect_ratio),
                response_modalities=['TEXT', 'IMAGE'] # لضمان استرجاع البصمة والنصوص
            )
        )

        returned_signature = None
        output_filename = f"gen_{os.urandom(4).hex()}.png"
        output_path = os.path.join(IMAGE_DIR, output_filename)

        # 5. استخراج النتائج من الـ Parts (نفس المنطق في مثالك الناجح)
        if not response or not response.parts:
             return None, None

        for part in response.parts:
            # صيد بصمة التفكير (Signature)
            if hasattr(part, 'thought_signature') and part.thought_signature:
                returned_signature = part.thought_signature
                print(f"✅ Found Thought Signature! Length: {len(returned_signature)}")

            # صيد الصورة وحفظها
            if part.inline_data:
                img = Image.open(BytesIO(part.inline_data.data))
                img.save(output_path)
                print(f"✅ Image Saved to: {output_path}")

        if os.path.exists(output_path):
            return output_path, returned_signature
            
        return None, None

    except Exception as e:
        if model_name == IMAGE_MODEL_NAME:
            print(f"⚠️ Primary Model Failed, trying alternative model: {IMAGE_MODEL_NAME_ALT}")
            return generate_image(prompt, reference_image_path, aspect_ratio, thought_signature, model_name=IMAGE_MODEL_NAME_ALT)
        print(f"❌ Generation Failed: {e}")
        return None, None

    
if __name__ == "__main__":
    # مثال تجريبي
    prompt = " Photorealistic image of a luxurious and sophisticated private study or an elegant modern majlis, meticulously designed for a discerning gentleman. The room features subtle, intricate Islamic geometric patterns integrated into dark wood wall panels and a rich, deep emerald green velvet armchair. Warm, volumetric lighting, reminiscent of a golden hour sunset, streams through a tall, arched window, casting elegant shadows and illuminating the opulent textures of polished dark wood surfaces and brushed gold decorative accents. An ornate, understated metal decorative lantern (without a visible light source or flame), inspired by traditional craftsmanship, rests on a pristine side table, reflecting the soft, ambient glow. The overall atmosphere is one of refined elegance, quiet prestige, and subtle festivity, hinting at a moment of celebration and luxury. Ample empty, sleek, dark wood surface space is left in the foreground, perfectly poised for product placement. Cinematic, hyper-detailed, 8k, rendered in Octane Render, utilizing professional studio lighting techniques to enhance depth and texture. --ar 4:3"
    reference_image = r"rawaj-frontend/assets/upload/098e521f-54d9-46f3-852b-98e9005ddb0e.jpg"  # ضع مسار صورة المنتج هنا
    thought_signature = ""  # ضع بصمة التفكير هنا إذا كانت متوفرة (اختياري)
    output_path, signature = generate_image(prompt, reference_image_path=reference_image, aspect_ratio="16:9", thought_signature=thought_signature)
    print(f"Generated Image Path: {output_path}")
    # print(f"Returned Thought Signature: {signature}")